css:
.uv-cd {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-cd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  display: inline-flex;
  align-items: center;
  gap: .7em;
  font-size: var(--s);
  color: var(--fg);
  cursor: pointer;
}

.uv-cd input {
  display: none;
}

.uv-cd span {
  display: grid;
  place-items: center;
  width: 1.6em;
  height: 1.6em;
  border-radius: .45em;
  box-shadow: inset 0 0 0 2px color-mix(in srgb,var(--fg) 25%,transparent);
  transition: all calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-cd svg {
  width: 70%;
  fill: none;
  stroke: #fff;
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1) calc(0.1s / var(--k));
}

.uv-cd input:checked+span {
  background: var(--c1);
  box-shadow: inset 0 0 0 2px var(--c1);
  animation: uv-pop calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-cd input:checked+span svg {
  stroke-dashoffset: 0;
}

@keyframes uv-pop {
  50% {
    transform: scale(1.2);
  }
}

