  gap: .7em;
  padding: .8em 1.1em;
  border-radius: 1em;
  font-size: var(--s);
  color: var(--fg);
  background: color-mix(in srgb,var(--fg) 5%,transparent);
  cursor: pointer;
}

.uv-ct input {
  display: none;
}

.uv-ct span {
  display: grid;
  place-items: center;
  width: 1.4em;
  height: 1.4em;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px color-mix(in srgb,var(--fg) 30%,transparent);
  transition: all calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-ct svg {
  width: 65%;
  fill: none;
  stroke: #fff;
  stroke-width: 3;
  stroke-linecap: round;
