  stroke-dashoffset: 1;
  transition: stroke-dashoffset calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ct em {
  position: relative;
  font-style: normal;
  transition: opacity calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ct em::after {
  content: "";
  position: absolute;
  left: -2%;
  top: 52%;
  width: 104%;
  height: 2px;
  border-radius: 2px;
  background: var(--c1);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ct input:checked~span {
  background: var(--c1);
  box-shadow: none;
}

.uv-ct input:checked~span svg {
  stroke-dashoffset: 0;
}

.uv-ct input:checked~em {
  opacity: .5;
}

.uv-ct input:checked~em::after {
  transform: scaleX(1);
}

