  --c1: #139fd0;
  --c2: #6fe0f2;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq02-liq {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: .75em;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  font-weight: 550;
}

.uvq02-liq input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq02-liq .bx {
  position: relative;
  display: grid;
  place-items: center;
  flex: none;
  width: 2.1em;
  height: 2.1em;
  border-radius: .6em;
  overflow: hidden;
  isolation: isolate;
  background: color-mix(in srgb,var(--c1) 6%,transparent);
  box-shadow: inset 0 0 0 2px color-mix(in srgb,var(--fg) 24%,transparent);
}

.uvq02-liq .bx::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(130deg,rgba(255,255,255,.55),transparent 35%);
  box-shadow: inset 0 0 0 2px color-mix(in srgb,var(--c1) 0%,transparent);
  z-index: 3;
  pointer-events: none;
  transition: box-shadow calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq02-liq .w1,.uvq02-liq .w2 {
  position: absolute;
  left: -95%;
  top: 115%;
  width: 290%;
  aspect-ratio: 1;
  border-radius: 42%;
  background: var(--c1);
  animation: uvq02-liq calc(5s / var(--k)) linear infinite;
  transition: top calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq02-liq .w2 {
  background: var(--c2);
  border-radius: 38%;
  animation-duration: calc(7s / var(--k));
  animation-direction: reverse;
}

.uvq02-liq .bu {
  position: absolute;
  bottom: .2em;
  left: 30%;
  width: .22em;
  height: .22em;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.85);
  opacity: 0;
  z-index: 1;
}

.uvq02-liq .bu + .bu {
  left: 62%;
  width: .16em;
  height: .16em;
}

.uvq02-liq svg {
  position: relative;
  z-index: 2;
  width: 1.15em;
  height: 1.15em;
  color: #fff;
  transform: scale(0);
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq02-liq:hover input:not(:checked) + .bx .w1 {
  top: 92%;
}

.uvq02-liq:hover input:not(:checked) + .bx .w2 {
  top: 88%;
}

.uvq02-liq:active .bx {
  scale: .94;
}

.uvq02-liq input:checked + .bx .w1 {
  top: 10%;
}

.uvq02-liq input:checked + .bx .w2 {
  top: 4%;
}

.uvq02-liq input:checked + .bx::after {
  box-shadow: inset 0 0 0 2px var(--c1);
}

.uvq02-liq input:checked + .bx svg {
  transform: scale(1);
  transition-delay: calc(0.45s / var(--k));
}

.uvq02-liq input:checked + .bx .bu {
  animation: uvq02-liq-b calc(1.2s / var(--k)) cubic-bezier(.25,.1,.25,1) calc(0.3s / var(--k));
}

.uvq02-liq input:checked + .bx .bu + .bu {
  animation-delay: calc(0.55s / var(--k));
}

@keyframes uvq02-liq {
  to {
    transform: rotate(360deg);
  }
}

@keyframes uvq02-liq-b {
  0% {
    opacity: 0;
    transform: none;
  }
  20% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translate(.15em,-1.6em);
  }
}

.uvq02-liq input:focus-visible + .bx {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@media (prefers-reduced-motion:reduce) {
  .uvq02-liq,.uvq02-liq *,.uvq02-liq *::before,.uvq02-liq *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

