  border-radius: 1em;
  background: rgba(44,42,38,.13);
}

.uvq02-dog .ls i:nth-child(2) {
  width: 92%;
}

.uvq02-dog .ls i:nth-child(3) {
  width: 97%;
}

.uvq02-dog .ls i:nth-child(4) {
  width: 58%;
}

