}

.uvq02-dog:hover {
  --uvq02-d: .9em;
}

.uvq02-dog:has(input:checked) {
  --uvq02-d: 2.6em;
}

.uvq02-dog:active .pg {
  background-color: color-mix(in srgb,var(--c2) 94%,#000);
}

.uvq02-dog:active {
  --uvq02-d: 1.4em;
}

.uvq02-dog:has(input:checked) .tx {
  color: color-mix(in srgb,var(--c1) 70%,#2c2a26);
}

.uvq02-dog:has(input:focus-visible) {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

