document.querySelectorAll(".uvq02-fpr").forEach(el => {
  const i = el.querySelector("input");
  let t = 0;
  const k = () => parseFloat(getComputedStyle(el).getPropertyValue("--k")) || 1;
  const stop = () => { clearTimeout(t); t = 0; el.classList.remove("hd"); };
  const done = () => { stop(); i.checked = !i.checked; i.dispatchEvent(new Event("change", { bubbles: true })); };
  el.addEventListener("pointerdown", (e) => {
    if (e.button > 0) return;
    e.preventDefault();
    el.classList.add("hd");
    t = setTimeout(done, 1000 / k());
  });
  ["pointerup", "pointerleave", "pointercancel"].forEach((n) => el.addEventListener(n, () => t && stop()));
  el.addEventListener("contextmenu", (e) => e.preventDefault());
  i.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); i.click(); } });
  return stop;
});

