document.querySelectorAll(".uvq02-swp").forEach(el => {
  const i = el.querySelector("input");
  const f = el.querySelector(".fg");
  let x0 = null, dx = 0, mv = false;
  const set = (v) => { if (i.checked !== v) { i.checked = v; i.dispatchEvent(new Event("change", { bubbles: true })); } };
  el.addEventListener("pointerdown", (e) => { x0 = e.clientX; dx = 0; mv = false; });
  el.addEventListener("pointermove", (e) => {
    if (x0 === null) return;
    dx = e.clientX - x0;
    if (!mv && Math.abs(dx) > 6) { mv = true; el.classList.add("dr"); el.setPointerCapture(e.pointerId); }
    if (mv) { const w = el.offsetWidth; f.style.transform = "translateX(" + Math.max(-w * 0.6, Math.min(w * 0.6, dx)) + "px)"; }
  });
  const up = () => {
    if (x0 === null) return;
    if (mv) { const w = el.offsetWidth; if (dx > w * 0.3) set(true); else if (dx < -w * 0.3) set(false); }
    x0 = null; f.style.transform = ""; el.classList.remove("dr");
  };
  el.addEventListener("pointerup", up);
  el.addEventListener("pointercancel", up);
  el.addEventListener("click", (e) => { if (mv) { e.preventDefault(); mv = false; } }, true);
  i.addEventListener("keydown", (e) => {
    if (e.key === "ArrowRight") { e.preventDefault(); set(true); }
    else if (e.key === "ArrowLeft") { e.preventDefault(); set(false); }
    else if (e.key === "Enter") { e.preventDefault(); set(!i.checked); }
  });
});

