}

.uvq02-gas input:checked + .bn .cp::after {
  animation: uvq02-gas-k calc(0.3s / var(--k)) steps(2) 1;
}

@keyframes uvq02-gas {
  to {
    scale: .9 .78;
  }
}

@keyframes uvq02-gas-k {
  50% {
    opacity: 1;
  }
}

